SELECT i.INSTALLMENT_ID, i.LOAN_ID, l.LOAN_ACCOUNT_NO, l.APPLICATION_ID, a.APPLICATION_NO, i.INSTALLMENT_NO, i.DUE_DATE, i.BORROWER_DUE, i.SUBSIDY_DUE, i.TOTAL_DUE, i.PAID_AMOUNT, i.PAYMENT_STATUS_CODE, GREATEST(TRUNC(SYSDATE) - i.DUE_DATE,0) DAYS_PAST_DUE, GREATEST(NVL(i.TOTAL_DUE,0) - NVL(i.PAID_AMOUNT,0),0) OUTSTANDING_DUE FROM MFF_INSTALLMENTS i JOIN MFF_LOANS l ON l.LOAN_ID = i.LOAN_ID JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID = l.APPLICATION_ID WHERE i.PAYMENT_STATUS_CODE IN ('DUE','PARTIAL','OVERDUE');
